//! Render the canonical source into each agent's own files.
//! Paths and formats follow `docs/target-matrix.md`.

use crate::config::{Agent, Config};
use crate::md::split_front;
use crate::source::{Item, McpServer, Source, front_get};
use serde_json::{Map, Value, json};
use std::collections::BTreeSet;

pub const HEADER_MD: &str =
    "<!-- generated by tempa from AGENTS.md and .tempa/ — do not edit; run \"tempa sync\" -->";

pub fn header_toml() -> String {
    "# generated by tempa from AGENTS.md and .tempa/ — do not edit; run \"tempa sync\"".to_string()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OutFile {
    pub path: String,
    pub bytes: Vec<u8>,
}

/// Something in the source this agent cannot read from a project file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Gap {
    pub agent: Agent,
    /// "commands" | "agents" | "skills" | "settings-deny" | "mcp"
    pub kind: &'static str,
    pub name: String,
}

#[derive(Debug, Clone, Default)]
pub struct Rendered {
    pub files: Vec<OutFile>,
    pub gaps: Vec<Gap>,
}

/// Dirs fully owned by tempa for an agent; anything else inside is untracked drift.
pub fn managed_dirs(agent: Agent) -> &'static [&'static str] {
    match agent {
        Agent::Claude => &[".claude/commands", ".claude/agents", ".claude/skills"],
        Agent::Codex => &[".codex/agents", ".agents/skills"],
        Agent::Gemini => &[".gemini/commands", ".gemini/agents", ".agents/skills"],
        Agent::Opencode => &[".opencode/commands", ".opencode/agents", ".agents/skills"],
        Agent::Cursor => &[".cursor/commands", ".cursor/agents", ".agents/skills"],
    }
}

struct Out {
    agent: Agent,
    r: Rendered,
}

impl Out {
    fn file(&mut self, path: impl Into<String>, text: impl Into<Vec<u8>>) {
        self.r.files.push(OutFile {
            path: path.into(),
            bytes: text.into(),
        });
    }

    fn gap(&mut self, kind: &'static str, name: &str) {
        self.r.gaps.push(Gap {
            agent: self.agent,
            kind,
            name: name.to_string(),
        });
    }
}

/// Header right after the frontmatter (frontmatter must stay on line 1).
fn with_header(front_raw: Option<&str>, body: &str) -> String {
    match front_raw {
        Some(raw) => format!("---\n{raw}---\n{HEADER_MD}\n{body}"),
        None => format!("{HEADER_MD}\n{body}"),
    }
}

/// Frontmatter built from chosen pairs only.
fn front_of(pairs: &[(&str, &str)]) -> String {
    pairs
        .iter()
        .map(|(k, v)| format!("{k}: {}\n", yaml_scalar(v)))
        .collect()
}

/// Plain YAML scalar when safe, else a JSON-quoted string (valid YAML).
fn yaml_scalar(v: &str) -> String {
    let unsafe_plain = v.is_empty()
        || v != v.trim()
        || v.contains(": ")
        || v.contains(" #")
        || v.contains('\n')
        || v.ends_with(':')
        || v.starts_with([
            '!', '&', '*', '-', '?', '{', '}', '[', ']', ',', '#', '|', '>', '@', '`', '"', '\'',
            '%',
        ]);
    if unsafe_plain {
        serde_json::to_string(v).expect("string serializes")
    } else {
        v.to_string()
    }
}

/// Rewrite each `${VAR}` (source syntax) with `f(VAR)`.
fn env_refs(v: &str, f: impl Fn(&str) -> String) -> String {
    let mut out = String::new();
    let mut rest = v;
    while let Some(i) = rest.find("${") {
        let Some(j) = rest[i..].find('}') else { break };
        out.push_str(&rest[..i]);
        out.push_str(&f(&rest[i + 2..i + j]));
        rest = &rest[i + j + 1..];
    }
    out + rest
}

/// `${VAR}` → OpenCode `{env:VAR}`.
fn opencode_env(v: &str) -> String {
    env_refs(v, |n| format!("{{env:{n}}}"))
}

/// `${VAR}` → Cursor `${env:VAR}` (cursor.com/docs/context/mcp), in every string.
fn cursor_env(v: &mut Value) {
    match v {
        Value::String(s) => {
            *s = env_refs(s, |n| match n.strip_prefix("env:") {
                Some(_) => format!("${{{n}}}"),
                None => format!("${{env:{n}}}"),
            })
        }
        Value::Array(a) => a.iter_mut().for_each(cursor_env),
        Value::Object(m) => m.values_mut().for_each(cursor_env),
        _ => {}
    }
}

/// Subagent with `name` (default: file stem) and `description` frontmatter.
fn named_agent(a: &Item) -> String {
    let name = front_get(a, "name").unwrap_or_else(|| stem(&a.rel));
    let mut pairs = vec![("name", name)];
    if let Some(d) = front_get(a, "description") {
        pairs.push(("description", d));
    }
    with_header(Some(&front_of(&pairs)), &a.body)
}

/// opencode.ai/docs/permissions: `permission.edit` maps globs to allow/ask/deny, the last
/// match wins, so `*` (the user's default) stays first. False when `permission` is not an
/// object (a string applies to every tool; left as the user wrote it).
fn opencode_deny(v: &mut Map<String, Value>, cfg: &Config) -> bool {
    let perm = v.entry("permission").or_insert_with(|| json!({}));
    let Some(perm) = perm.as_object_mut() else {
        return false;
    };
    let mut edit = match perm.remove("edit") {
        Some(Value::Object(m)) => m,
        Some(Value::String(s)) => Map::from_iter([("*".to_string(), json!(s))]),
        _ => Map::from_iter([("*".to_string(), json!("allow"))]),
    };
    // ponytail: serde_json sorts keys; `*` sorts before any glob starting with a letter, `.` or `/`.
    for p in &cfg.gates.protected_paths {
        edit.insert(
            p.trim_start_matches("./").trim_start_matches('/').into(),
            json!("deny"),
        );
    }
    perm.insert("edit".into(), Value::Object(edit));
    true
}

/// Append one deny rule per protected path to `v.permissions.deny`, keeping what is there.
fn merge_deny(v: &mut Map<String, Value>, cfg: &Config, rule: impl Fn(&str) -> String) {
    let perms = v.entry("permissions").or_insert_with(|| json!({}));
    if !perms.is_object() {
        *perms = json!({});
    }
    let perms = perms.as_object_mut().expect("object");
    let mut deny: Vec<Value> = perms
        .get("deny")
        .and_then(|d| d.as_array().cloned())
        .unwrap_or_default();
    for p in &cfg.gates.protected_paths {
        let r = json!(rule(p.trim_start_matches("./").trim_start_matches('/')));
        if !deny.contains(&r) {
            deny.push(r);
        }
    }
    perms.insert("deny".into(), Value::Array(deny));
}

fn opencode_map(m: &std::collections::BTreeMap<String, String>) -> Value {
    Value::Object(
        m.iter()
            .map(|(k, v)| (k.clone(), json!(opencode_env(v))))
            .collect(),
    )
}

fn item_raw(item: &Item) -> String {
    with_header(item.front.as_ref().map(|f| f.raw.as_str()), &item.body)
}

fn stem(rel: &str) -> &str {
    let name = rel.rsplit('/').next().unwrap_or(rel);
    name.strip_suffix(".md").unwrap_or(name)
}

fn base_json(src: &Source, path: &str) -> Map<String, Value> {
    src.bases
        .get(path)
        .and_then(|b| serde_json::from_slice::<Value>(b).ok())
        .and_then(|v| v.as_object().cloned())
        .unwrap_or_default()
}

fn pretty(v: &Map<String, Value>) -> String {
    serde_json::to_string_pretty(v).expect("json map serializes") + "\n"
}

/// `{command,args,env}` or the agent's remote shape.
fn mcp_json(s: &McpServer, remote: impl Fn(&str) -> Value) -> Value {
    if let Some(url) = &s.url {
        let mut v = remote(url);
        if !s.headers.is_empty() {
            v["headers"] = json!(s.headers);
        }
        return v;
    }
    let mut m = Map::new();
    m.insert(
        "command".into(),
        json!(s.command.clone().unwrap_or_default()),
    );
    if !s.args.is_empty() {
        m.insert("args".into(), json!(s.args));
    }
    if !s.env.is_empty() {
        m.insert("env".into(), json!(s.env));
    }
    Value::Object(m)
}

fn mcp_map(src: &Source, remote: impl Fn(&str) -> Value + Copy) -> Value {
    Value::Object(
        src.mcp
            .iter()
            .map(|(n, s)| (n.clone(), mcp_json(s, remote)))
            .collect(),
    )
}

/// Write `<path>` with `key` replaced by the MCP map, when there is MCP or a base file.
fn mcp_file(
    out: &mut Out,
    src: &Source,
    path: &str,
    key: &str,
    remote: impl Fn(&str) -> Value + Copy,
) {
    if src.mcp.is_empty() && !src.bases.contains_key(path) {
        return;
    }
    let mut v = base_json(src, path);
    if !src.mcp.is_empty() {
        v.insert(key.into(), mcp_map(src, remote));
    }
    out.file(path, pretty(&v));
}

fn skills(out: &mut Out, src: &Source, dir: &str) {
    for skill in &src.skills {
        for (rel, bytes) in &skill.files {
            let path = format!("{dir}/{}/{rel}", skill.name);
            if rel == "SKILL.md" {
                let text = String::from_utf8_lossy(bytes);
                let (front, body) = split_front(&text);
                let body = crate::md::normalize_eol(body);
                out.file(
                    path,
                    with_header(front.as_ref().map(|f| f.raw.as_str()), &body),
                );
            } else {
                out.file(path, bytes.clone());
            }
        }
    }
}

fn deny_gaps(out: &mut Out, cfg: &Config) {
    for p in &cfg.gates.protected_paths {
        out.gap("settings-deny", p);
    }
}

fn toml_basic(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

fn toml_multiline(s: &str) -> String {
    format!(
        "\"\"\"\n{}\"\"\"",
        s.replace('\\', "\\\\").replace("\"\"\"", "\"\"\\\"")
    )
}

/// Claude command syntax → Gemini: `$ARGUMENTS` → `{{args}}`, `` !`cmd` `` → `!{cmd}`,
/// `@path` (a word with `/` or `.`) → `@{path}`.
fn gemini_prompt(body: &str) -> String {
    let mut s = body.replace("$ARGUMENTS", "{{args}}");
    while let Some(i) = s.find("!`") {
        let Some(j) = s[i + 2..].find('`') else { break };
        let cmd = s[i + 2..i + 2 + j].to_string();
        s.replace_range(i..i + 3 + j, &format!("!{{{cmd}}}"));
    }
    let mut out = String::with_capacity(s.len());
    let mut prev_ws = true;
    let mut rest = s.as_str();
    while let Some(ch) = rest.chars().next() {
        if ch == '@' && prev_ws {
            let word: String = rest[1..]
                .chars()
                .take_while(|c| !c.is_whitespace())
                .collect();
            let path = word.trim_end_matches([',', ';', ':', ')', '.']);
            if !path.is_empty()
                && (path.contains('/') || path.contains('.'))
                && !path.starts_with('{')
            {
                out.push_str(&format!("@{{{path}}}"));
                rest = &rest[1 + path.len()..];
                prev_ws = false;
                continue;
            }
        }
        out.push(ch);
        prev_ws = ch.is_whitespace();
        rest = &rest[ch.len_utf8()..];
    }
    out
}

/// `${NAME}` → `NAME`.
fn env_ref(v: &str) -> Option<&str> {
    v.strip_prefix("${")
        .and_then(|r| r.strip_suffix('}'))
        .filter(|n| !n.is_empty() && !n.contains(['$', '{', '}']))
}

/// Codex `[mcp_servers.x]` entries for env/headers. Codex passes `env` and
/// `http_headers` literally, forwards host vars by the same name (`env_vars`), reads
/// header values from named vars (`env_http_headers`) and a bearer token from
/// `bearer_token_env_var`. Anything else with `${..}` cannot be expressed → gap.
fn codex_mcp(out: &mut Out, name: &str, s: &McpServer, t: &mut toml_edit::Table) {
    let (mut env, mut fwd) = (toml_edit::InlineTable::new(), toml_edit::Array::new());
    for (k, v) in &s.env {
        match env_ref(v) {
            Some(n) if n == k => fwd.push(n),
            _ if v.contains("${") => out.gap(
                "mcp",
                &format!("{name}: env {k}={v} (Codex cannot rename variables)"),
            ),
            _ => {
                env.insert(k, v.as_str().into());
            }
        }
    }
    let (mut hdr, mut env_hdr) = (toml_edit::InlineTable::new(), toml_edit::InlineTable::new());
    for (k, v) in &s.headers {
        if let Some(n) = env_ref(v) {
            env_hdr.insert(k, n.into());
        } else if let Some(n) = v
            .strip_prefix("Bearer ")
            .and_then(env_ref)
            .filter(|_| k.eq_ignore_ascii_case("authorization"))
        {
            t.insert("bearer_token_env_var", toml_edit::value(n));
        } else if v.contains("${") {
            out.gap(
                "mcp",
                &format!("{name}: header {k} (value format not supported by Codex)"),
            );
        } else {
            hdr.insert(k, v.as_str().into());
        }
    }
    for (key, table) in [
        ("env", env),
        ("http_headers", hdr),
        ("env_http_headers", env_hdr),
    ] {
        if !table.is_empty() {
            t.insert(key, toml_edit::value(table));
        }
    }
    if !fwd.is_empty() {
        t.insert("env_vars", toml_edit::value(fwd));
    }
}

fn codex_config(out: &mut Out, src: &Source) {
    let path = ".codex/config.toml";
    if src.mcp.is_empty() && !src.bases.contains_key(path) {
        return;
    }
    let mut doc: toml_edit::DocumentMut = src
        .bases
        .get(path)
        .and_then(|b| String::from_utf8_lossy(b).parse().ok())
        .unwrap_or_default();
    if !src.mcp.is_empty() {
        let mut servers = toml_edit::Table::new();
        servers.set_implicit(true);
        for (name, s) in &src.mcp {
            let mut t = toml_edit::Table::new();
            if let Some(url) = &s.url {
                t.insert("url", toml_edit::value(url));
            } else {
                t.insert(
                    "command",
                    toml_edit::value(s.command.clone().unwrap_or_default()),
                );
                if !s.args.is_empty() {
                    t.insert(
                        "args",
                        toml_edit::value(s.args.iter().collect::<toml_edit::Array>()),
                    );
                }
            }
            codex_mcp(out, name, s, &mut t);
            servers.insert(name, toml_edit::Item::Table(t));
        }
        doc.insert("mcp_servers", toml_edit::Item::Table(servers));
    }
    out.file(path, format!("{}\n{}", header_toml(), doc));
}

/// Name of the server `tempa sync` adds for `tempa mcp`.
pub const TEMPA_SERVER: &str = "tempa";

/// True when render adds the `tempa` server (a user server of that name wins).
pub fn injects_tempa(cfg: &Config, src: &Source) -> bool {
    cfg.mcp.serve && !src.mcp.contains_key(TEMPA_SERVER)
}

pub fn render(agent: Agent, cfg: &Config, src: &Source) -> Rendered {
    let inject = injects_tempa(cfg, src);
    let with_tempa;
    let src = if inject {
        let mut s = src.clone();
        s.mcp.insert(
            TEMPA_SERVER.into(),
            McpServer {
                command: Some("tempa".into()),
                args: vec!["mcp".into()],
                ..McpServer::default()
            },
        );
        with_tempa = s;
        &with_tempa
    } else {
        src
    };
    let mut out = Out {
        agent,
        r: Rendered::default(),
    };
    let o = &mut out;
    match agent {
        Agent::Claude => {
            let mut claude = format!("{HEADER_MD}\n\n@{}\n", cfg.docs.context);
            if let Some(extra) = &src.claude_extra {
                claude.push('\n');
                claude.push_str(extra);
            }
            o.file("CLAUDE.md", claude);
            for c in &src.commands {
                o.file(format!(".claude/commands/{}", c.rel), item_raw(c));
            }
            for a in &src.agents {
                o.file(format!(".claude/agents/{}", a.rel), item_raw(a));
            }
            skills(o, src, ".claude/skills");

            let path = ".claude/settings.json";
            let mut v = base_json(src, path);
            merge_deny(&mut v, cfg, |p| format!("Edit(/{p})"));
            if inject {
                // Claude Code asks before starting a project `.mcp.json` server unless listed here.
                let list = v
                    .entry("enabledMcpjsonServers")
                    .or_insert_with(|| json!([]));
                if !list.is_array() {
                    *list = json!([]);
                }
                let list = list.as_array_mut().expect("array");
                if !list.iter().any(|x| x == TEMPA_SERVER) {
                    list.push(json!(TEMPA_SERVER));
                }
            }
            o.file(path, pretty(&v));

            mcp_file(
                o,
                src,
                ".mcp.json",
                "mcpServers",
                |u| json!({"type":"http","url":u}),
            );
        }
        Agent::Codex => {
            for c in &src.commands {
                o.gap("commands", &c.rel);
            }
            // learn.chatgpt.com/docs/agent-configuration/subagents: one TOML file per agent.
            for a in &src.agents {
                let name = front_get(a, "name").unwrap_or_else(|| stem(&a.rel));
                let mut t = header_toml() + "\n";
                t += &format!("name = {}\n", toml_basic(name));
                if let Some(d) = front_get(a, "description") {
                    t += &format!("description = {}\n", toml_basic(d));
                }
                t += &format!("developer_instructions = {}\n", toml_multiline(&a.body));
                let file = stem(&a.rel).replace('/', "-");
                o.file(format!(".codex/agents/{file}.toml"), t);
            }
            skills(o, src, ".agents/skills");
            deny_gaps(o, cfg);
            codex_config(o, src);
        }
        Agent::Gemini => {
            for c in &src.commands {
                let mut t = header_toml() + "\n";
                if let Some(d) = front_get(c, "description") {
                    t += &format!("description = {}\n", toml_basic(d));
                }
                if (1..=9).any(|n| c.body.contains(&format!("${n}"))) {
                    o.gap(
                        "commands",
                        &format!("{} ($1..$9 not supported by Gemini; use $ARGUMENTS)", c.rel),
                    );
                }
                t += &format!("prompt = {}\n", toml_multiline(&gemini_prompt(&c.body)));
                let rel = c.rel.strip_suffix(".md").unwrap_or(&c.rel);
                o.file(format!(".gemini/commands/{rel}.toml"), t);
            }
            for a in &src.agents {
                o.file(format!(".gemini/agents/{}", a.rel), named_agent(a));
            }
            skills(o, src, ".agents/skills");
            deny_gaps(o, cfg);

            let path = ".gemini/settings.json";
            let mut v = base_json(src, path);
            let ctx = v.entry("context").or_insert_with(|| json!({}));
            if !ctx.is_object() {
                *ctx = json!({});
            }
            ctx.as_object_mut()
                .expect("object")
                .insert("fileName".into(), json!([cfg.docs.context]));
            if !src.mcp.is_empty() {
                v.insert("mcpServers".into(), mcp_map(src, |u| json!({"httpUrl":u})));
            }
            o.file(path, pretty(&v));
        }
        Agent::Opencode => {
            for c in &src.commands {
                let front = front_get(c, "description").map(|d| front_of(&[("description", d)]));
                o.file(
                    format!(".opencode/commands/{}", c.rel),
                    with_header(front.as_deref(), &c.body),
                );
            }
            for a in &src.agents {
                let desc = front_get(a, "description").unwrap_or_else(|| stem(&a.rel));
                let front = front_of(&[("description", desc), ("mode", "subagent")]);
                o.file(
                    format!(".opencode/agents/{}", a.rel),
                    with_header(Some(&front), &a.body),
                );
            }
            skills(o, src, ".agents/skills");

            let path = "opencode.json";
            let deny = !cfg.gates.protected_paths.is_empty();
            if !src.mcp.is_empty() || src.bases.contains_key(path) || deny {
                let mut v = base_json(src, path);
                if deny && !opencode_deny(&mut v, cfg) {
                    deny_gaps(o, cfg);
                }
                // OpenCode adds this key itself when it runs; render it so that is not drift.
                v.entry("$schema")
                    .or_insert_with(|| json!("https://opencode.ai/config.json"));
                if !src.mcp.is_empty() {
                    let servers = src
                        .mcp
                        .iter()
                        .map(|(n, s)| {
                            let val = match &s.url {
                                Some(u) => {
                                    let mut m = json!({"type":"remote","url":u});
                                    if !s.headers.is_empty() {
                                        m["headers"] = opencode_map(&s.headers);
                                    }
                                    m
                                }
                                None => {
                                    let mut cmd = vec![s.command.clone().unwrap_or_default()];
                                    cmd.extend(s.args.iter().cloned());
                                    let mut m = json!({"type":"local","command":cmd});
                                    if !s.env.is_empty() {
                                        m["environment"] = opencode_map(&s.env);
                                    }
                                    m
                                }
                            };
                            (n.clone(), val)
                        })
                        .collect();
                    v.insert("mcp".into(), Value::Object(servers));
                }
                o.file(path, pretty(&v));
            }
        }
        Agent::Cursor => {
            // Context: Cursor reads AGENTS.md itself (cursor.com/docs/rules).
            for c in &src.commands {
                o.file(
                    format!(".cursor/commands/{}", c.rel),
                    with_header(None, &c.body),
                );
            }
            // Cursor also reads .claude/agents/ and .codex/agents/ (cursor.com/docs/subagents).
            if !cfg
                .agents
                .enabled
                .iter()
                .any(|a| matches!(a, Agent::Claude | Agent::Codex))
            {
                for a in &src.agents {
                    o.file(format!(".cursor/agents/{}", a.rel), named_agent(a));
                }
            }
            skills(o, src, ".agents/skills");

            // cursor.com/docs/cli/reference/permissions: the CLI honours this; the IDE may not.
            let path = ".cursor/cli.json";
            let mut v = base_json(src, path);
            merge_deny(&mut v, cfg, |p| format!("Write({p})"));
            o.file(path, pretty(&v));

            let path = ".cursor/mcp.json";
            if !src.mcp.is_empty() || src.bases.contains_key(path) {
                let mut v = base_json(src, path);
                if !src.mcp.is_empty() {
                    let mut servers = mcp_map(src, |u| json!({"type":"http","url":u}));
                    cursor_env(&mut servers);
                    v.insert("mcpServers".into(), servers);
                }
                o.file(path, pretty(&v));
            }
        }
    }
    out.r
}

/// All enabled agents; identical shared paths (`.agents/skills`) emitted once; sorted by path.
pub fn render_all(cfg: &Config, src: &Source) -> Rendered {
    let mut all = Rendered::default();
    let mut seen = BTreeSet::new();
    for agent in &cfg.agents.enabled {
        let r = render(*agent, cfg, src);
        for f in r.files {
            if seen.insert(f.path.clone()) {
                all.files.push(f);
            }
        }
        all.gaps.extend(r.gaps);
    }
    all.files.sort_by(|a, b| a.path.cmp(&b.path));
    all
}
